actions.script:
const found = context.document || {}
const current = Array.from(found.fromRelationships || []).filter(row => row && row.employmentThruDate == null)
const restricted = ["QualIdentityDocument", "QualWorkPermit"].includes(found.qualificationTypeEnumId)
context.document = Object.assign({}, found, {fromRelationships: current},
    current.length ? {} : {noCurrentEmployment: "Y"}, restricted ? {restrictedType: "Y"} : {})
